'use client'
/** Timer: the MATRIX card `timer`. Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { henryBoard } from '@/lib/matrix/widgets/boards/henry'

const preset = henryBoard.find(p => p.id === 'timer')!

export type MatrixTimerProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixTimer(props: MatrixTimerProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
